-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` WHEN 'pairings' THEN b.`pairings` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'H. Upmann' hote, 'celebrities' champ
        UNION ALL SELECT 'H. Upmann' hote, 'gamme' champ
        UNION ALL SELECT 'H. Upmann' hote, 'history' champ
        UNION ALL SELECT 'H. Upmann' hote, 'pairings' champ
        UNION ALL SELECT 'Montecristo' hote, 'celebrities' champ
        UNION ALL SELECT 'Montecristo' hote, 'gamme' champ
        UNION ALL SELECT 'Montecristo' hote, 'history' champ
        UNION ALL SELECT 'Montecristo' hote, 'pairings' champ
        UNION ALL SELECT 'Partagás' hote, 'gamme' champ
        UNION ALL SELECT 'Partagás' hote, 'history' champ
        UNION ALL SELECT 'Partagás' hote, 'pairings' champ
        UNION ALL SELECT 'Bolivar' hote, 'gamme' champ
        UNION ALL SELECT 'Bolivar' hote, 'history' champ
        UNION ALL SELECT 'Bolivar' hote, 'pairings' champ
        UNION ALL SELECT 'Hoyo de Monterrey' hote, 'celebrities' champ
        UNION ALL SELECT 'Hoyo de Monterrey' hote, 'gamme' champ
        UNION ALL SELECT 'Hoyo de Monterrey' hote, 'history' champ
        UNION ALL SELECT 'Hoyo de Monterrey' hote, 'pairings' champ
        UNION ALL SELECT 'Punch' hote, 'celebrities' champ
        UNION ALL SELECT 'Punch' hote, 'gamme' champ
        UNION ALL SELECT 'Punch' hote, 'history' champ
        UNION ALL SELECT 'Punch' hote, 'pairings' champ
        UNION ALL SELECT 'Romeo y Julieta' hote, 'celebrities' champ
        UNION ALL SELECT 'Romeo y Julieta' hote, 'gamme' champ
        UNION ALL SELECT 'Romeo y Julieta' hote, 'history' champ
        UNION ALL SELECT 'Romeo y Julieta' hote, 'pairings' champ
        UNION ALL SELECT 'Trinidad' hote, 'celebrities' champ
        UNION ALL SELECT 'Trinidad' hote, 'gamme' champ
        UNION ALL SELECT 'Trinidad' hote, 'history' champ
        UNION ALL SELECT 'Trinidad' hote, 'pairings' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

