UNION ALL SELECT 'H. Upmann', 'fr', 'source (correction)', (LOCATE(CAST('habanos.com « H. Upmann Brand » (https://www.habanos.com/en/the-world-of-the-habano/the-habanos-brands-academia/h-upmann-brand/, page sans date, lue le 15 octobre 2026 : Herman Upmann, banquier allemand, s''installe à La Havane en 1844, y fonde une banque et une fabrique de Habanos ; médailles d''or de la boîte gagnées dans au moins onze foires internationales au XIXe siècle ; force légère à moyenne ; Magnum 50 en 2008, Half Corona en 2011, Magnum 54 en 2016, Sir Winston Gran Reserva en 2017) et habanos.com « H. Upmann » en espagnol (https://www.habanos.com/es/marca-h-upmann/, page sans date, lue le 15 octobre 2026 : installation en 1840, banque et fabrique en 1844)' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'H. Upmann'
