UNION ALL SELECT 'Montecristo', 'ar', 'histoire 5 (nouveau texte)', (LOCATE(CAST('ويفتتح Edmundo (cepo 52 x 135 مم)، الذي قُدِّم في باريس في 13 مايو 2004، وPetit Edmundo (2007) خطًّا ذا نكهة متوسطة إلى كاملة، بحسب الدار؛ وتربط ويكيبيديا الاسم ببطل الرواية Edmond Dantès، من دون مصدر. أما Línea Montecristo Open، التي قُدِّمت في Festival del Habano عام 2009، فتضم أربعة قياسات هي Eagle وMaster وRegata وJunior، متوسطة القوة. وLínea 1935 (Maltés وDumas وLeyenda)، المعلن عنها في مارس 2018، هي، بحسب habanos.com، أول خلطة كاملة القوة في العلامة. ومن الإصدارات الحديثة 80 Aniversario (2015) وDantés (2016) وSupremos (2019) وElba (2025، بمناسبة تسعين عامًا على العلامة).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Montecristo'
UNION ALL SELECT 'Montecristo', 'ar', 'histoire 5 (ancien texte parti)', (LOCATE(CAST('وأضاف «إدموندو»، الصادر عام 2004، طابعًا أكثر استدارة وأقرب تناولًا. وحملت سلسلة «أوبن» العلامة إلى مدخّنين أصغر سنًّا وجدوا الكلاسيكيات متطلّبة بعض الشيء. أما «لا لينيا 1492»، التي أُنشئت عام 1992 في الذكرى الخمسمئة لرحلة كولومبوس، فأعطت «سوبليميس» — دبل كورونا يتطوّر على نحو مختلف من علبة إلى أخرى.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Montecristo'
UNION ALL SELECT 'Montecristo', 'fr', 'histoire 6 (nouveau texte)', (LOCATE(CAST('Parmi les plus récents, le Brillantes (cepo 53 x 128 mm) a été lancé à Hong Kong en février 2024 pour l''année du Dragon, et le Fragata (cepo 54 x 140 mm), humidor de voyage de vingt cigares, a été présenté le 1er octobre 2026 pour les seuls circuits duty free et travel retail.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Montecristo'
