UNION ALL SELECT 'Montecristo', 'fr', 'source (correction)', (LOCATE(CAST('habanos.com « Montecristo Brand » (https://www.habanos.com/en/the-habanos-brands-academia/montecristo-brand/, page sans date, lue le 15 octobre 2026 :' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Montecristo'
