UNION ALL SELECT 'Montecristo', 'fr', 'source (correction)', (LOCATE(CAST(' ; en.wikipedia.org « Montecristo (cigar) » et « Alexandre Dumas » (fabrique Particulares en juillet 1935, usine H. Upmann en 1937, Canaries puis La Romana ; mort de Dumas le 5 décembre 1870)' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Montecristo'
