UNION ALL SELECT 'Hoyo de Monterrey', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Fabrique mère La Corona (Miguel Fernández Roig), Cerro, La Havane, fabrique de cigares depuis 2000 (ancienne fabrique de cigarettes) ; Punch y est aussi produite, dit habanos.com' AS BINARY)) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Hoyo de Monterrey doit son origine à la plantation du même nom, à San Juan y Martínez, dans la Vuelta Abajo, dit habanos.com, qui ne donne pas d''année de fondation de la marque. Wikipédia rattache le nom à un terrain concave que les cultivateurs de tabac recherchent, et la presse du métier au bassin de Monterrey. La marque a été enregistrée en 1865 par José Gener, disent Wikipédia et la presse du métier. Wikipédia le fait émigrer d''Espagne à treize ans, en 1831, ouvrir une fabrique à La Havane, puis acheter avec ses profits une ferme de tabac de la Vuelta Abajo avant d''enregistrer la marque ; la presse du métier l''appelle un Cubain et date de 1860 l''achat de la plantation.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Hoyo de Monterrey tire son nom d''un véritable « hoyo » — un creux naturel dans les collines de Vuelta Abajo, non loin de San Juan y Martínez — réputé produire le tabac le plus doux et le plus aromatique de toute Cuba. José Gener, fabricant espagnol installé à La Havane, fonda la marque en 1865 spécifiquement pour exploiter ce terroir d''exception.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Hoyo de Monterrey owes its origin to the plantation of the same name, at San Juan y Martínez, in the Vuelta Abajo, says habanos.com, which gives no founding year for the brand. Wikipedia links the name to a concave piece of land that tobacco growers look for, and the trade press to the Monterrey basin. The brand was registered in 1865 by José Gener, say Wikipedia and the trade press. Wikipedia has him emigrate from Spain at thirteen, in 1831, open a factory in Havana, then buy a tobacco farm in the Vuelta Abajo with his profits before registering the brand; the trade press calls him a Cuban and dates the purchase of the plantation to 1860.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Hoyo de Monterrey takes its name from a genuine "hoyo" — a natural hollow in the hills of Vuelta Abajo, near San Juan y Martínez — long reputed to produce the softest and most aromatic tobacco in all of Cuba. José Gener, a Spanish manufacturer established in Havana, founded the brand in 1865 specifically to exploit this exceptional terroir.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Hoyo de Monterrey debe su origen a la plantación del mismo nombre, en San Juan y Martínez, en la Vuelta Abajo, dice habanos.com, que no da año de fundación de la marca. Wikipedia vincula el nombre a un terreno cóncavo que buscan los cultivadores de tabaco, y la prensa del oficio a la cuenca de Monterrey. La marca fue registrada en 1865 por José Gener, dicen Wikipedia y la prensa del oficio. Wikipedia lo hace emigrar de España a los trece años, en 1831, abrir una fábrica en La Habana y luego comprar con sus beneficios una finca de tabaco de la Vuelta Abajo antes de registrar la marca; la prensa del oficio lo llama cubano y fecha en 1860 la compra de la plantación.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Hoyo de Monterrey debe su nombre a un auténtico «hoyo» —una hondonada natural en las lomas de Vuelta Abajo, no lejos de San Juan y Martínez— con fama de dar el tabaco más suave y aromático de toda Cuba. José Gener, fabricante español establecido en La Habana, fundó la marca en 1865 precisamente para explotar ese terruño excepcional.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Hoyo de Monterrey verdankt seinen Ursprung der gleichnamigen Plantage in San Juan y Martínez, in der Vuelta Abajo, sagt habanos.com, das kein Gründungsjahr der Marke nennt. Wikipedia führt den Namen auf ein konkaves Gelände zurück, das Tabakpflanzer suchen, die Fachpresse auf das Becken von Monterrey. Die Marke wurde 1865 von José Gener eingetragen, sagen Wikipedia und die Fachpresse. Wikipedia lässt ihn mit dreizehn Jahren, 1831, aus Spanien auswandern, in Havanna eine Fabrik eröffnen und dann mit seinen Gewinnen eine Tabakfarm in der Vuelta Abajo kaufen, bevor er die Marke eintrug; die Fachpresse nennt ihn einen Kubaner und datiert den Kauf der Plantage auf 1860.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Hoyo de Monterrey verdankt seinen Namen einem echten „hoyo“ — einer natürlichen Senke in den Hügeln der Vuelta Abajo, unweit von San Juan y Martínez —, der nachgesagt wird, den mildesten und aromatischsten Tabak ganz Kubas hervorzubringen. José Gener, ein in Havanna niedergelassener spanischer Fabrikant, gründete die Marke 1865 eigens, um dieses außergewöhnliche Terroir zu nutzen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Hoyo de Monterrey 的渊源来自同名种植园，位于 Vuelta Abajo 的 San Juan y Martínez，habanos.com 如是说，但它没有给出该品牌的创立年份。维基百科把这个名字与烟农所寻找的一处凹形地块联系起来，行业媒体则联系到 Monterrey 盆地。该品牌于1865年由 José Gener 注册，维基百科和行业媒体都这么说。维基百科称他十三岁时（1831年）从西班牙移民，在哈瓦那开办工厂，随后用所得利润买下 Vuelta Abajo 的一座烟草农场，再注册该品牌；行业媒体称他为古巴人，并把购买种植园的时间定在1860年。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Hoyo de Monterrey 的名字源自一个真实的「hoyo」——Vuelta Abajo 丘陵间一处天然凹地，距 San Juan y Martínez 不远，素以出产全古巴最柔和、最芬芳的烟叶著称。定居哈瓦那的西班牙制造商 José Gener 于 1865 年创立该品牌，正是为了开发这片非凡的风土。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('يعود أصل Hoyo de Monterrey إلى المزرعة التي تحمل الاسم نفسه في San Juan y Martínez بمنطقة Vuelta Abajo، بحسب habanos.com، التي لا تذكر سنة تأسيس للعلامة. وتربط ويكيبيديا الاسم بأرض مقعّرة يبحث عنها مزارعو التبغ، وتربطه الصحافة المتخصّصة بحوض Monterrey. وقد سُجّلت العلامة عام 1865 على يد José Gener، كما تقول ويكيبيديا والصحافة المتخصّصة. وتذكر ويكيبيديا أنه هاجر من إسبانيا في الثالثة عشرة، عام 1831، وفتح مصنعًا في هافانا، ثم اشترى بأرباحه ضيعة تبغ في Vuelta Abajo قبل أن يسجّل العلامة؛ وتسمّيه الصحافة المتخصّصة كوبيًّا وتؤرّخ شراء المزرعة بعام 1860.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('يستمدّ Hoyo de Monterrey اسمه من «hoyo» حقيقي — منخفض طبيعي في تلال Vuelta Abajo، غير بعيد عن San Juan y Martínez — يُقال إنه ينتج أنعم تبغ في كوبا وأغناه عطراً. وقد أسّس José Gener، وهو صانع إسباني مقيم في هافانا، العلامة عام 1865 خصيصاً لاستثمار هذه الأرض الاستثنائية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Wikipédia écrit que la marque devint populaire, surtout sur le marché britannique ; que José Gener mourut en 1900, sa fille Lutgarda dirigeant ensuite l''affaire une trentaine d''années ; et que la firme Fernández, Palicio y Cía acheta en 1931 Hoyo de Monterrey et La Escepción, en les ajoutant à un portefeuille qui comprenait déjà Punch et Belinda.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La particularité géographique du hoyo original est documentée depuis le XVIIIe siècle. L''enfoncement topographique crée un microclimat de chaleur et d''humidité légèrement supérieures au reste de la région, favorisant une maturation plus lente des feuilles et une concentration en huiles aromatiques remarquable. Les cultivateurs de l''époque réservaient ces parcelles aux capes de leurs meilleurs cigares.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Wikipedia writes that the brand became popular, especially in the British market; that José Gener died in 1900, his daughter Lutgarda then running the business for some thirty years; and that the firm Fernández, Palicio y Cía bought Hoyo de Monterrey and La Escepción in 1931, adding them to a portfolio that already included Punch and Belinda.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The geographic peculiarity of the original hollow has been documented since the eighteenth century. The topographic depression creates a microclimate of slightly higher heat and humidity than the surrounding region, favoring slower leaf maturation and a remarkable concentration of aromatic oils. Farmers of the era reserved these plots for the wrappers of their finest cigars.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Wikipedia escribe que la marca se hizo popular, sobre todo en el mercado británico; que José Gener murió en 1900 y que su hija Lutgarda dirigió después el negocio unos treinta años; y que la firma Fernández, Palicio y Cía compró en 1931 Hoyo de Monterrey y La Escepción, sumándolas a un portafolio que ya incluía Punch y Belinda.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('La singularidad geográfica del hoyo original está documentada desde el siglo XVIII. El hundimiento del terreno crea un microclima algo más cálido y húmedo que el resto de la comarca, lo que favorece una maduración más lenta de las hojas y una notable concentración de aceites aromáticos. Los cultivadores de la época reservaban esas parcelas para las capas de sus mejores puros.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Wikipedia schreibt, die Marke sei beliebt geworden, vor allem auf dem britischen Markt; José Gener sei 1900 gestorben, seine Tochter Lutgarda habe das Geschäft danach etwa dreißig Jahre geleitet; und die Firma Fernández, Palicio y Cía habe 1931 Hoyo de Monterrey und La Escepción gekauft und einem Portfolio hinzugefügt, das schon Punch und Belinda umfasste.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die geografische Besonderheit des ursprünglichen Hoyo ist seit dem 18. Jahrhundert belegt. Die Geländesenke schafft ein Mikroklima mit etwas höherer Wärme und Feuchtigkeit als die übrige Region, was ein langsameres Reifen der Blätter und eine bemerkenswerte Konzentration aromatischer Öle begünstigt. Die Pflanzer jener Zeit behielten diese Parzellen den Deckblättern ihrer besten Zigarren vor.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('维基百科写道，该品牌广受欢迎，尤其是在英国市场；José Gener 于1900年去世，其女 Lutgarda 此后经营这门生意约三十年；Fernández, Palicio y Cía 公司于1931年买下 Hoyo de Monterrey 与 La Escepción，并将二者并入一个原已包含 Punch 与 Belinda 的品牌组合。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('这处原始凹地的地理特殊性自 18 世纪起便有记载。地势下陷造就了比周边稍暖稍湿的小气候，有利于烟叶更缓慢地成熟，并积聚出可观的芳香油脂。当时的种植者把这些地块专门留给最好雪茄的茄衣。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('وتكتب ويكيبيديا أنّ العلامة نالت شعبية، ولا سيما في السوق البريطانية؛ وأنّ José Gener توفي عام 1900، وأنّ ابنته Lutgarda أدارت العمل بعده نحو ثلاثين عامًا؛ وأنّ شركة Fernández, Palicio y Cía اشترت عام 1931 العلامتين Hoyo de Monterrey وLa Escepción، وضمّتهما إلى محفظة كانت تضمّ أصلًا Punch وBelinda.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('خصوصية هذا المنخفض الجغرافية موثّقة منذ القرن الثامن عشر. فالانخفاض في التضاريس يخلق مناخاً محلياً أشدّ حرارة ورطوبة قليلاً من بقية المنطقة، ما يبطئ نضج الأوراق ويرفع تركيز زيوتها العطرية إلى حدّ لافت. وكان مزارعو ذلك العهد يخصّصون هذه القطع لأغلفة أفخر سيجارهم.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Wikipédia écrit que le gouvernement révolutionnaire nationalisa les fabriques de cigares en 1959, que Fernando Palicio quitta Cuba pour la Floride et vendit ses marques à la famille Villazon ; un Hoyo de Monterrey hondurien est aujourd''hui fabriqué par General Cigar, et c''est un autre cigare. Le Hoyo de Monterrey cubain est celui de Habanos S.A., qui le décrit comme une marque de force douce, en feuilles de la Vuelta Abajo, roulée à la main en tripe longue.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Après la nationalisation de 1960, Hoyo de Monterrey rejoignit le portefeuille Habanos et fut positionnée comme la marque emblématique du profil cubain doux — une alternative aux puissances de Partagás ou Bolívar pour les amateurs cherchant complexité sans intensité. Cette position lui valut un succès particulier sur les marchés britannique et scandinave.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Wikipedia writes that the revolutionary government nationalised the cigar factories in 1959, that Fernando Palicio left Cuba for Florida and sold his brands to the Villazon family; a Honduran Hoyo de Monterrey is today made by General Cigar, and it is a different cigar. The Cuban Hoyo de Monterrey is the one from Habanos S.A., which describes it as a brand of mild strength, made with Vuelta Abajo leaves, rolled by hand with longfiller.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('After nationalization in 1960, Hoyo de Monterrey joined the Habanos portfolio and was positioned as the emblematic brand of the Cuban soft profile — an alternative to the power of Partagás or Bolívar for those seeking complexity without intensity. This positioning earned it particular success in the British and Scandinavian markets.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Wikipedia escribe que el gobierno revolucionario nacionalizó las fábricas de puros en 1959, que Fernando Palicio dejó Cuba por Florida y vendió sus marcas a la familia Villazon; hoy General Cigar fabrica un Hoyo de Monterrey hondureño, y es otro puro. El Hoyo de Monterrey cubano es el de Habanos S.A., que lo describe como una marca de fuerza suave, con hojas de la Vuelta Abajo, liada a mano con tripa larga.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Tras la nacionalización de 1960, Hoyo de Monterrey pasó al catálogo de Habanos y se posicionó como la marca emblemática del perfil cubano suave: una alternativa a la potencia de Partagás o Bolívar para quienes buscan complejidad sin intensidad. Esa posición le valió un éxito particular en los mercados británico y escandinavo.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Wikipedia schreibt, die revolutionäre Regierung habe 1959 die Zigarrenfabriken verstaatlicht, Fernando Palicio habe Kuba in Richtung Florida verlassen und seine Marken an die Familie Villazon verkauft; ein honduranischer Hoyo de Monterrey wird heute von General Cigar hergestellt, und das ist eine andere Zigarre. Der kubanische Hoyo de Monterrey ist der von Habanos S.A., die ihn als Marke von milder Stärke beschreibt, aus Blättern der Vuelta Abajo, von Hand gerollt mit Longfiller.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Nach der Verstaatlichung von 1960 kam Hoyo de Monterrey ins Habanos-Portfolio und wurde als Aushängeschild des milden kubanischen Profils positioniert — eine Alternative zur Kraft von Partagás oder Bolívar für Liebhaber, die Komplexität ohne Intensität suchen. Diese Stellung brachte ihr auf dem britischen und dem skandinavischen Markt besonderen Erfolg.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('维基百科写道，革命政府于1959年将雪茄工厂国有化，Fernando Palicio 离开古巴前往佛罗里达，把自己的品牌卖给了 Villazon 家族；如今洪都拉斯的 Hoyo de Monterrey 由 General Cigar 生产，那是另一种雪茄。古巴的 Hoyo de Monterrey 属于 Habanos S.A.，后者称它为力度柔和的品牌，采用 Vuelta Abajo 的烟叶，以长茄芯手工卷制。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('1960 年国有化之后，Hoyo de Monterrey 并入 Habanos 旗下，被定位为古巴柔和风格的标志性品牌——为追求复杂度而不求强度的爱好者，提供 Partagás 或 Bolívar 之外的选择。这一定位使它在英国与北欧市场格外成功。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('وتكتب ويكيبيديا أنّ الحكومة الثورية أمّمت مصانع السيجار عام 1959، وأنّ Fernando Palicio غادر كوبا إلى فلوريدا وباع علاماته إلى عائلة Villazon؛ وتصنع General Cigar اليوم Hoyo de Monterrey هندوراسيًّا، وهو سيجار آخر. أمّا Hoyo de Monterrey الكوبي فهو سيجار Habanos S.A.، التي تصفه بأنه علامة خفيفة القوة، من أوراق Vuelta Abajo، تُلفّ يدويًّا بحشوة طويلة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('بعد تأميم 1960، انضمّ Hoyo de Monterrey إلى محفظة Habanos ووُضع بوصفه العلامة الأبرز للطابع الكوبي الناعم — بديلاً عن قوة Partagás أو Bolívar لمن يبحث عن التعقيد دون الشدّة. وقد أكسبه هذا الموقع نجاحاً خاصاً في السوقين البريطانية والإسكندنافية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('La ligne Epicure réunit, selon habanos.com, l''Epicure No. 1, l''Epicure No. 2 et l''Epicure Especial, à la présentation distincte ; l''Epicure Especial fut une Edición Limitada en 2004 avant d''entrer au portefeuille régulier en 2008, et un communiqué de décembre 2024 fait de l''Epicure No. 3 (cepo 54 x 125 mm, premier figurado de la marque) la quatrième vitola de la ligne. En octobre 2016, habanos.com écrivait de l''Epicure No. 2 Reserva Cosecha 2012 qu''il est un symbole de la marque.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La gamme Epicure, introduite dans les années 1970, devint la série la plus emblématique. Crémeux, floraux, avec des notes de bois blanc, de noisette et une finale légèrement mielleuse, les Epicure restent parmi les cigares cubains les plus célébrés. Le No.2 est le Robusto cubain doux de référence mondiale — un statut qu''il conserve après cinq décennies et qu''aucun concurrent n''a entièrement détrôné.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('The Epicure line brings together, according to habanos.com, the Epicure No. 1, the Epicure No. 2 and the Epicure Especial, with a distinct presentation; the Epicure Especial was an Edición Limitada in 2004 before joining the regular portfolio in 2008, and a December 2024 press release makes the Epicure No. 3 (cepo 54 x 125 mm, the brand''s first figurado) the fourth vitola of the line. In October 2016, habanos.com wrote of the Epicure No. 2 Reserva Cosecha 2012 that it is a symbol of the brand.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The Epicure line, introduced in the 1970s, became the house''s most iconic series. Creamy, floral, with notes of white wood, hazelnut, and a slightly honeyed finish, the Epicures remain among the most celebrated Cuban cigars. The No.2 is the world reference for gentle Cuban robustos — a status it has maintained for five decades that no competitor has entirely dethroned.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('La línea Epicure reúne, según habanos.com, el Epicure No. 1, el Epicure No. 2 y el Epicure Especial, de presentación distinta; el Epicure Especial fue una Edición Limitada en 2004 antes de entrar en el portafolio regular en 2008, y un comunicado de diciembre de 2024 hace del Epicure No. 3 (cepo 54 x 125 mm, primer figurado de la marca) la cuarta vitola de la línea. En octubre de 2016, habanos.com escribía del Epicure No. 2 Reserva Cosecha 2012 que es un símbolo de la marca.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La gama Epicure, presentada en los años setenta, se convirtió en la serie más emblemática. Cremosos, florales, con notas de madera blanca y avellana y un final ligeramente melado, los Epicure siguen estando entre los puros cubanos más celebrados. El No.2 es el Robusto cubano suave de referencia mundial: una condición que conserva cinco décadas después y que ningún competidor le ha arrebatado del todo.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Die Epicure-Linie vereint laut habanos.com die Epicure No. 1, die Epicure No. 2 und die Epicure Especial in eigener Aufmachung; die Epicure Especial war 2004 eine Edición Limitada, bevor sie 2008 ins reguläre Portfolio kam, und eine Pressemitteilung vom Dezember 2024 macht die Epicure No. 3 (cepo 54 x 125 mm, erstes Figurado der Marke) zur vierten Vitola der Linie. Im Oktober 2016 schrieb habanos.com über die Epicure No. 2 Reserva Cosecha 2012, sie sei ein Symbol der Marke.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Die in den 1970er Jahren eingeführte Epicure-Linie wurde zur sinnbildlichen Serie. Cremig, blumig, mit Noten von hellem Holz und Haselnuss und einem leicht honigartigen Abgang, zählen die Epicure weiterhin zu den gefeiertsten kubanischen Zigarren. Die No.2 ist der weltweit maßgebliche milde kubanische Robusto — ein Rang, den sie nach fünf Jahrzehnten behauptet und den ihr kein Konkurrent je ganz streitig gemacht hat.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('据 habanos.com，Epicure 系列包含 Epicure No. 1、Epicure No. 2 与 Epicure Especial，包装呈现自成一格；Epicure Especial 于2004年为 Edición Limitada，2008年起进入常规产品组合，而2024年12月的一份新闻稿将 Epicure No. 3（cepo 54 x 125 mm，该品牌首支 figurado）列为该系列的第四个规格。2016年10月，habanos.com 写道，Epicure No. 2 Reserva Cosecha 2012 是该品牌的象征。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
