UNION ALL SELECT 'Hoyo de Monterrey', 'en', 'gamme Epicure (vitolas)', (JSON_LENGTH(JSON_EXTRACT(`gamme_en`, '$[0].vitolas')) = 4) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'en', 'gamme Epicure (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_en`, '$[0].story')) AS BINARY) = CAST('Habanos groups the Epicure No. 1, the Epicure No. 2 and the Epicure Especial in a line with a distinct presentation, and a December 2024 press release adds the Epicure No. 3, cepo 54 x 125 mm, the brand''s first figurado. The Epicure No. 1 measures 143 mm for a cepo 46, the Epicure No. 2 124 mm for a cepo 50 (its Reserva Cosecha 2012 dates from 2016) and the Epicure Especial 141 mm for a cepo 50 (Edición Limitada in 2004, regular portfolio since 2008). Habanos describes the brand as mild in strength.' AS BINARY)) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'gamme Epicure', (JSON_CONTAINS(JSON_EXTRACT(`gamme_es`, '$[*].name'), '"Epicure"')) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'gamme Epicure (vitolas)', (JSON_LENGTH(JSON_EXTRACT(`gamme_es`, '$[0].vitolas')) = 4) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
UNION ALL SELECT 'Hoyo de Monterrey', 'es', 'gamme Epicure (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_es`, '$[0].story')) AS BINARY) = CAST('Habanos reúne el Epicure No. 1, el Epicure No. 2 y el Epicure Especial en una línea de presentación distinta, y un comunicado de diciembre de 2024 le añade el Epicure No. 3, cepo 54 x 125 mm, primer figurado de la marca. El Epicure No. 1 mide 143 mm con cepo 46, el Epicure No. 2 124 mm con cepo 50 (su Reserva Cosecha 2012 data de 2016) y el Epicure Especial 141 mm con cepo 50 (Edición Limitada en 2004, portafolio regular desde 2008). Habanos describe la marca como de fuerza suave.' AS BINARY)) FROM `brands` WHERE `name` = 'Hoyo de Monterrey'
